"use strict";
import { useAccount } from "hooks/useAccount";
import { useReadContract } from "wagmi";
import { contractAddresses, contractABIs } from "uniswap/src/constants/cl-contracts";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { ProtocolVersion } from "@uniswap/client-pools/dist/pools/v1/types_pb";
import { useMemo } from "react";
export function useGaugeRewards(position, gaugeAddress) {
  const { address, chainId } = useAccount();
  const isTestnet = chainId === UniverseChainId.AbstractTestnet;
  const isMainnet = chainId === UniverseChainId.AbstractMainnet;
  const networkContracts = isTestnet ? { addresses: contractAddresses.abstractTestnet, abis: contractABIs.abstractTestnet } : isMainnet ? { addresses: contractAddresses.abstractMainnet, abis: contractABIs.abstractMainnet } : null;
  const isV3 = position?.version === ProtocolVersion.V3;
  const tokenId = position?.tokenId;
  const { data: v3EarnedRewards } = useReadContract({
    address: gaugeAddress,
    abi: networkContracts?.abis.CLGauge,
    functionName: "earned",
    args: tokenId ? [BigInt(tokenId)] : void 0,
    enabled: Boolean(gaugeAddress && networkContracts?.abis.CLGauge && tokenId && isV3),
    watch: true,
    query: {
      refetchInterval: 3e4,
      // Refetch every 30 seconds for real-time rewards
      staleTime: 15e3
      // Consider stale after 15 seconds
    }
  });
  const { data: v2EarnedRewards } = useReadContract({
    address: gaugeAddress,
    abi: [
      {
        "inputs": [{ "internalType": "address", "name": "account", "type": "address" }],
        "name": "earned",
        "outputs": [{ "internalType": "uint256", "name": "", "type": "uint256" }],
        "stateMutability": "view",
        "type": "function"
      }
    ],
    functionName: "earned",
    args: address ? [address] : void 0,
    enabled: Boolean(gaugeAddress && address && !isV3),
    watch: true,
    query: {
      refetchInterval: 3e4,
      staleTime: 15e3
    }
  });
  const { data: v3StakedBalance } = useReadContract({
    address: gaugeAddress,
    abi: networkContracts?.abis.CLGauge,
    functionName: "balanceOf",
    args: tokenId ? [BigInt(tokenId)] : void 0,
    enabled: Boolean(gaugeAddress && networkContracts?.abis.CLGauge && tokenId && isV3),
    watch: true,
    query: {
      refetchInterval: 6e4,
      staleTime: 3e4
    }
  });
  const { data: v2StakedBalance } = useReadContract({
    address: gaugeAddress,
    abi: [
      {
        "inputs": [{ "internalType": "address", "name": "account", "type": "address" }],
        "name": "balanceOf",
        "outputs": [{ "internalType": "uint256", "name": "", "type": "uint256" }],
        "stateMutability": "view",
        "type": "function"
      }
    ],
    functionName: "balanceOf",
    args: address ? [address] : void 0,
    enabled: Boolean(gaugeAddress && address && !isV3),
    watch: true,
    query: {
      refetchInterval: 6e4,
      staleTime: 3e4
    }
  });
  const { data: rewardRate } = useReadContract({
    address: gaugeAddress,
    abi: [
      {
        "inputs": [],
        "name": "rewardRate",
        "outputs": [{ "internalType": "uint256", "name": "", "type": "uint256" }],
        "stateMutability": "view",
        "type": "function"
      }
    ],
    functionName: "rewardRate",
    enabled: Boolean(gaugeAddress),
    query: {
      refetchInterval: 3e5,
      // Refetch every 5 minutes
      staleTime: 12e4
      // Consider stale after 2 minutes
    }
  });
  const { data: totalSupply } = useReadContract({
    address: gaugeAddress,
    abi: [
      {
        "inputs": [],
        "name": "totalSupply",
        "outputs": [{ "internalType": "uint256", "name": "", "type": "uint256" }],
        "stateMutability": "view",
        "type": "function"
      }
    ],
    functionName: "totalSupply",
    enabled: Boolean(gaugeAddress),
    query: {
      refetchInterval: 3e5,
      staleTime: 12e4
    }
  });
  return useMemo(() => {
    const earnedRewards = isV3 ? v3EarnedRewards : v2EarnedRewards;
    const stakedBalance = isV3 ? v3StakedBalance : v2StakedBalance;
    const earnedAmount = earnedRewards ? (Number(earnedRewards) / 1e18).toFixed(6) : "0";
    const stakedAmount = stakedBalance ? (Number(stakedBalance) / 1e18).toFixed(6) : "0";
    const rewardRatePerSecond = rewardRate ? Number(rewardRate) / 1e18 : 0;
    const totalStakedAmount = totalSupply ? Number(totalSupply) / 1e18 : 0;
    let apr = "N/A";
    if (rewardRatePerSecond > 0 && totalStakedAmount > 0) {
      const yearlyRewards = rewardRatePerSecond * 31536e3;
      const aprValue = yearlyRewards / totalStakedAmount * 100;
      apr = aprValue.toFixed(2) + "%";
    }
    return {
      // Rewards data
      earnedRewards: earnedAmount,
      pendingRewards: earnedAmount,
      // Same as earned for display purposes
      // Staking data  
      stakedBalance: stakedAmount,
      isStaked: Number(stakedAmount) > 0,
      // Pool-wide stats
      rewardRate: rewardRatePerSecond.toFixed(6),
      totalSupply: totalStakedAmount.toFixed(2),
      apr,
      // Loading states
      isLoading: false,
      // We have default values, so never really loading
      // Raw data for advanced use
      raw: {
        earnedRewards,
        stakedBalance,
        rewardRate,
        totalSupply
      }
    };
  }, [v3EarnedRewards, v2EarnedRewards, v3StakedBalance, v2StakedBalance, rewardRate, totalSupply, isV3]);
}
export function useMultiGaugeRewards(positions) {
  const rewards = positions.map(
    ({ position, gaugeAddress }) => useGaugeRewards(position, gaugeAddress)
  );
  return useMemo(() => {
    const totalEarnedRewards = rewards.reduce((sum, reward) => sum + Number(reward.earnedRewards), 0);
    const totalStakedBalance = rewards.reduce((sum, reward) => sum + Number(reward.stakedBalance), 0);
    return {
      rewards,
      totalEarnedRewards: totalEarnedRewards.toFixed(6),
      totalStakedBalance: totalStakedBalance.toFixed(6),
      averageApr: rewards.length > 0 ? rewards.reduce((sum, r) => sum + (r.apr !== "N/A" ? Number(r.apr.replace("%", "")) : 0), 0) / rewards.length + "%" : "N/A"
    };
  }, [rewards]);
}
